def build_business_pages(business):
    pages={}
    from itmanager.schema import MODULES
    for key,(title,fields) in MODULES.items():
        data=business[key]
        pages['business-'+key]=(title+'：逐项使用指南','<p class="lead">'+escape(data['purpose'])+'</p>'+image('page-'+key,title+'列表')+'<h2>操作步骤与资料获取</h2>'+steps(data['steps'])+'<h2>字段逐项说明</h2>'+table([(field,data['fields'][field]) for field in fields])+image('form-'+key,title+'新建表单')+'<h2>示例（仅演示）</h2>'+table(list(data['example'].items()))+'<h2>形成闭环</h2>'+steps(data['closure'])+'<h2>常见误区与边界</h2>'+steps(data['pitfalls']))
    return pages
